<script setup lang="ts">
import CacheSyncLog from './CacheSyncLog.vue';
import {onMounted,onUnmounted,ref,watch} from 'vue';
const props=defineProps<{kind:'scan'|'refresh';disabled:boolean}>(),emit=defineEmits<{authenticationRequired:[]}>();
type Row={run_id:string;sequence:string;status:string;phase:string;current_directory:string;pages_processed:string;items_processed:string;pending_count:string;started_at_utc?:string;updated_at_utc?:string;recorded_at_utc?:string;kind?:string};
const runs=ref<Row[]>([]),events=ref<Row[]>([]),selected=ref(''),loading=ref(false),error=ref(''),opened=ref(false),runNext=ref('0'),eventNext=ref('0'),runMore=ref(false),eventMore=ref(false),observed=ref('');
let active=true,generation=0,controller:AbortController|undefined;
const exact=(x:unknown)=>typeof x==='string'&&/^(0|[1-9][0-9]*)$/.test(x)&&x.length<=19&&BigInt(x)<=9223372036854775807n;
function stop(){active=false;generation++;controller?.abort();loading.value=false;}
async function load(run='',next='0'){
 if(!active||props.disabled||loading.value)return;
 const request=++generation;controller=new AbortController();loading.value=true;error.value='';
 if(run!==selected.value){events.value=[];eventNext.value='0';eventMore.value=false;}selected.value=run;opened.value=true;
 const query=new URLSearchParams({identity_format:'string',limit:'20'});if(run)query.set('run_id',run);if(next!=='0')query.set('before_sequence',next);
 try{const response=await fetch('/api/cloud-inventory/'+props.kind+(run?'/events?':'/runs?')+query,{credentials:'same-origin',signal:controller.signal});if(request!==generation)return;if(response.status===401){stop();emit('authenticationRequired');return;}if(!response.ok)throw Error(await response.text()||'记录读取失败');const data=await response.json();if(request!==generation)return;
 if(!Array.isArray(data.rows)||data.rows.length>20||!exact(data.next_before_sequence)||typeof data.has_more!=='boolean'||(data.has_more&&(data.next_before_sequence==='0'||(next!=='0'&&BigInt(data.next_before_sequence)>=BigInt(next)))))throw Error('记录分页响应无效');
 let previous=next==='0'?9223372036854775808n:BigInt(next);
 for(const row of data.rows){if(!row||!/^[a-f0-9]{32}$/.test(row.run_id)||!['sequence','pages_processed','items_processed','pending_count'].every(key=>exact(row[key]))||BigInt(row.sequence)>=previous||typeof row.status!=='string'||typeof row.phase!=='string'||typeof row.current_directory!=='string'||(run&&row.run_id!==run))throw Error('记录身份或精确计数无效');const utc=run?row.recorded_at_utc:row.started_at_utc;if(typeof utc!=='string'||!utc.endsWith('Z')||!Number.isFinite(Date.parse(utc)))throw Error('记录时间无效');previous=BigInt(row.sequence);}
 if(run){events.value=data.rows;eventNext.value=data.next_before_sequence;eventMore.value=data.has_more;}else{runs.value=data.rows;runNext.value=data.next_before_sequence;runMore.value=data.has_more;}observed.value=new Date().toISOString();
 }catch(e:any){if(request===generation)error.value=e.message||'记录读取失败';}finally{if(request===generation)loading.value=false;}
}
function restore(event:PageTransitionEvent){if(event.persisted&&!props.disabled){active=true;if(opened.value)load(selected.value);}}
watch(()=>props.disabled,value=>{if(value)stop();});
onMounted(()=>{window.addEventListener('pagehide',stop);window.addEventListener('pageshow',restore);});
onUnmounted(()=>{stop();window.removeEventListener('pagehide',stop);window.removeEventListener('pageshow',restore);});
</script>
<template><section class="event-results" :data-testid="'cache-'+kind+'-history'"><header class="page-header"><h2>{{kind==='scan'?'全盘扫描记录':'目录刷新记录'}}</h2><button class="button secondary" :disabled="disabled||loading" @click="load()">{{opened?'刷新最近记录':'查看最近记录'}}</button></header><p class="muted">只读本地持久记录；查看与导出不会启动网盘扫描。{{kind==='refresh'?'逐项变更明细见新版扫描历史。':'完整运行与事件见扫描历史。'}} <a class="button secondary compact" :href="'/cloud/history?source='+kind+(selected?'&amp;run='+selected:'')">查看完整历史</a></p><p v-if="error" class="notice danger" role="alert">{{error}} · 已显示的数据来自上次读取。</p><template v-if="opened"><div class="event-table-scroll"><table><thead><tr><th>运行 / 开始 UTC</th><th>状态 / 阶段</th><th>页数 / 项目数</th><th>操作</th></tr></thead><tbody><tr v-for="run in runs" :key="run.run_id"><td>{{run.run_id}}<br>{{run.started_at_utc}}</td><td>{{run.status}} / {{run.phase}}</td><td>{{run.pages_processed}} / {{run.items_processed}}</td><td><button class="button secondary" data-testid="cache-run-open" :disabled="disabled||loading" @click="load(run.run_id)">查看事件</button></td></tr><tr v-if="!runs.length"><td colspan="4">暂无读取到的运行记录。</td></tr></tbody></table></div><button v-if="runMore" class="button secondary" :disabled="disabled||loading" @click="load('',runNext)">更早运行</button><div v-if="selected"><CacheSyncLog v-if="kind==='refresh'" :run="selected" :disabled="disabled"/><header class="page-header"><h3>固定运行 {{selected}}</h3><a :href="'/api/cloud-inventory/'+kind+'/runs/'+selected+'/export'" download>导出本轮 JSON 证据</a></header><p class="muted">导出包含原始整数与完整证据；原始文件应使用支持精确整数的工具读取。</p><div class="event-table-scroll"><table><thead><tr><th>事件 / 阶段</th><th>目录</th><th>页数 / 项目数</th><th>记录 UTC</th></tr></thead><tbody><tr v-for="event in events" :key="event.sequence"><td>{{event.kind}} / {{event.phase}}</td><td>{{event.current_directory}}</td><td>{{event.pages_processed}} / {{event.items_processed}}</td><td>{{event.recorded_at_utc}}</td></tr><tr v-if="!events.length"><td colspan="4">本页暂无事件，或尚未成功读取。</td></tr></tbody></table></div><button v-if="eventMore" class="button secondary" :disabled="disabled||loading" @click="load(selected,eventNext)">更早事件</button></div></template><p v-if="loading" role="status">正在读取记录…</p><p v-if="observed" class="muted">本机读取 UTC：{{observed}}</p></section></template>
